        {
          id: "s4",
          label: "Maintain continuous contact and atmospheric monitoring results relay, and order evacuation if readings or conditions change"
        },
        {
          id: "s5",
          label: "Establish and test voice or radio communication between attendant and entrant before the entrant descends"
        },
        {
          id: "s6",
          label: "Set up the retrieval system so the attendant can extract the entrant from outside without entering the space"
        }
